//! Writing generated files. The published directory is tracked by the shared
//! `.crucible` manifest of `crucible_codegen::write`, so only files crucible
//! generated are ever replaced or removed; handwritten files and `.git`
//! survive regeneration.

use std::io;
use std::path::Path;

use crucible_codegen::File;

pub(crate) fn write<'a>(
    out: &Path,
    files: impl IntoIterator<Item = (&'a str, &'a str)>,
) -> io::Result<()> {
    let files: Vec<File> = files
        .into_iter()
        .map(|(path, contents)| File {
            path: path.to_owned(),
            contents: contents.to_owned(),
        })
        .collect();
    crucible_codegen::write(out, &files)
}

#[cfg(test)]
mod tests {
    use std::fs;

    use super::write;

    #[test]
    fn regeneration_keeps_handwritten_files_and_git() {
        let root = tempfile::tempdir().unwrap();
        let out = root.path().join("out");
        write(&out, [("protocol-tests.json", "{}")]).unwrap();
        fs::write(out.join("README.md"), "mine").unwrap();
        fs::create_dir(out.join(".git")).unwrap();
        fs::write(out.join(".git/HEAD"), "ref").unwrap();
        write(&out, [("other.json", "[]")]).unwrap();
        assert_eq!(fs::read_to_string(out.join("README.md")).unwrap(), "mine");
        assert_eq!(fs::read_to_string(out.join(".git/HEAD")).unwrap(), "ref");
        assert!(out.join("other.json").is_file());
        assert!(!out.join("protocol-tests.json").exists());
    }

    #[test]
    fn legacy_marker_directory_is_adopted_without_deleting_anything() {
        let root = tempfile::tempdir().unwrap();
        fs::write(
            root.path().join(".crucible"),
            "Generated by crucible. This directory is emptied and rewritten on every run.
",
        )
        .unwrap();
        fs::write(root.path().join("README.md"), "mine").unwrap();
        write(root.path(), [("generated.json", "{}")]).unwrap();
        assert_eq!(
            fs::read_to_string(root.path().join("README.md")).unwrap(),
            "mine"
        );
        assert!(root.path().join("generated.json").is_file());
    }

    #[test]
    fn refuses_to_overwrite_a_file_it_does_not_own() {
        let root = tempfile::tempdir().unwrap();
        fs::write(root.path().join("generated.json"), "mine").unwrap();
        assert!(write(root.path(), [("generated.json", "{}")]).is_err());
        assert_eq!(
            fs::read_to_string(root.path().join("generated.json")).unwrap(),
            "mine"
        );
    }
}
